//
// Pixel-for-pixel replica of VS Code's agent-feedback editor widget
// (src/vs/sessions/contrib/agentFeedback/browser/agentFeedbackEditorWidgetContribution.ts,
// class AgentFeedbackEditorWidget). It builds the EXACT same DOM tree and reuses
// the verbatim CSS (vscodeCommentWidget.css) so we can compare our own comment
// rendering against VS Code's. It has NO Monaco / workbench-service dependency:
// the comment body is rendered with a tiny markdown shim and codicons are drawn
// via unicode placeholders (see vscodeCommentTokens.css).
//

export type VscodeCommentSource = 'agentFeedback' | 'prReview';

/** Mirrors AgentFeedbackKind; drives the type badge (see {@link _typeLabel}). */
export type VscodeCommentKind = 'userReview' | 'prReview' | 'agentReview';

export interface VscodeCommentSuggestionEdit {
    readonly startLine: number;
    readonly endLine?: number;
    readonly newText: string;
}

export interface VscodeComment {
    readonly id: string;
    readonly source: VscodeCommentSource;
    readonly kind: VscodeCommentKind;
    readonly startLine: number;
    readonly endLine?: number;
    readonly text: string;
    readonly suggestion?: { readonly edits: readonly VscodeCommentSuggestionEdit[] };
    readonly replies?: readonly string[];
}

export interface VscodeCommentWidgetOptions {
    readonly expanded?: boolean;
    readonly focusedCommentId?: string;
}

/** Per-item action affordances, mirroring VS Code's `ICommentItemActions`. */
interface ItemActions {
    edit: HTMLAnchorElement;
    remove: HTMLAnchorElement;
    addReply: HTMLAnchorElement;
    setEnabled(enabled: boolean): void;
}

const DOM_HELPER_TAG = /^([a-z0-9]+)/i;

/** VS Code's `dom.$('tag.a.b')` shorthand, reduced to what we use. */
function $(selector: string): HTMLElement {
    const tag = DOM_HELPER_TAG.exec(selector)?.[1] ?? 'div';
    const el = document.createElement(tag);
    const classes = selector.slice(tag.length).split('.').filter(Boolean);
    if (classes.length) {
        el.className = classes.join(' ');
    }
    return el;
}

/**
 * Inline Feather-style icons (stroke="currentColor"), matching the crisp look of
 * the editor's read-only lock toggle — far nicer than a unicode/font glyph. The
 * DOM keeps the real `codicon codicon-<name>` classes; the SVG is the glyph.
 */
function feather(inner: string): string {
    return `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${inner}</svg>`;
}

const ICON_SVGS: Record<string, string> = {
    'comment': feather('<path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path>'),
    'comment-discussion': feather('<path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"></path>'),
    'chevron-down': feather('<polyline points="6 9 12 15 18 9"></polyline>'),
    'chevron-up': feather('<polyline points="18 15 12 9 6 15"></polyline>'),
    'edit': feather('<path d="M12 20h9"></path><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"></path>'),
    'close': feather('<line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line>'),
};

/** A codicon span carrying the inline Feather SVG for `name`. */
function icon(name: string): HTMLElement {
    const span = $(`span.codicon.codicon-${name}`);
    span.setAttribute('aria-hidden', 'true');
    span.innerHTML = ICON_SVGS[name] ?? '';
    return span;
}

/**
 * Minimal markdown shim producing the same `.rendered-markdown > p` shape VS
 * Code's MarkdownRenderer emits for these single-paragraph comments, with inline
 * `` `code` `` support.
 */
function renderMarkdown(text: string): HTMLElement {
    const wrap = $('div.rendered-markdown');
    const p = document.createElement('p');
    for (const part of text.split(/(`[^`]+`)/g)) {
        if (/^`[^`]+`$/.test(part)) {
            const code = document.createElement('code');
            code.textContent = part.slice(1, -1);
            p.appendChild(code);
        } else if (part) {
            p.appendChild(document.createTextNode(part));
        }
    }
    wrap.appendChild(p);
    return wrap;
}

export class VscodeCommentWidget {
    private readonly _domNode: HTMLElement;
    private readonly _headerNode: HTMLElement;
    private readonly _titleNode: HTMLElement;
    private readonly _toggleButton: HTMLElement;
    private readonly _bodyNode: HTMLElement;

    private _isExpanded = false;
    private _focusedId: string | undefined;
    private readonly _itemElements = new Map<string, HTMLElement>();
    private readonly _disposables: (() => void)[] = [];

    get element(): HTMLElement { return this._domNode; }

    constructor(
        private readonly _comments: readonly VscodeComment[],
        options?: VscodeCommentWidgetOptions,
    ) {
        // Root — starts collapsed (matches production).
        this._domNode = $('div.agent-feedback-widget');
        this._domNode.classList.add('collapsed');
        this._domNode.tabIndex = -1;
        this._domNode.setAttribute('widgetid', 'agent-feedback-widget-0');

        // Header: comment icon + title + spacer + toggle.
        this._headerNode = $('div.agent-feedback-widget-header');
        this._headerNode.appendChild(icon('comment'));

        this._titleNode = $('span.agent-feedback-widget-title');
        this._updateTitle();
        this._headerNode.appendChild(this._titleNode);

        this._headerNode.appendChild($('span.agent-feedback-widget-spacer'));

        this._toggleButton = $('div.agent-feedback-widget-toggle');
        this._updateToggleButton();
        this._headerNode.appendChild(this._toggleButton);

        this._domNode.appendChild(this._headerNode);

        // Body (collapsible) — starts collapsed.
        this._bodyNode = $('div.agent-feedback-widget-body');
        this._bodyNode.classList.add('collapsed');
        this._buildFeedbackItems();
        this._domNode.appendChild(this._bodyNode);

        // Arrow pointer.
        this._domNode.appendChild($('div.agent-feedback-widget-arrow'));

        this._setupEventHandlers();

        this._domNode.classList.add('visible');

        if (options?.expanded) { this.expand(); }
        if (options?.focusedCommentId) { this.focusFeedback(options.focusedCommentId); }
    }

    // --- Header ----------------------------------------------------------

    private _updateTitle(): void {
        const count = this._comments.length;
        this._titleNode.textContent = count === 1 ? this._comments[0].text : `${count} comments`;
    }

    private _updateToggleButton(): void {
        this._toggleButton.textContent = '';
        if (this._isExpanded) {
            this._toggleButton.appendChild(icon('chevron-up'));
            this._toggleButton.title = 'Collapse';
        } else {
            this._toggleButton.appendChild(icon('chevron-down'));
            this._toggleButton.title = 'Expand';
        }
    }

    private _setupEventHandlers(): void {
        this._listen(this._toggleButton, 'click', e => { e.stopPropagation(); this._toggleExpanded(); });
        this._listen(this._headerNode, 'click', () => this._toggleExpanded());
    }

    private _toggleExpanded(): void {
        if (this._isExpanded) { this.collapse(); } else { this.expand(); }
    }

    // --- Items -----------------------------------------------------------

    private _buildFeedbackItems(): void {
        this._bodyNode.textContent = '';
        this._itemElements.clear();

        for (const comment of this._comments) {
            const item = $('div.agent-feedback-widget-item');
            item.classList.add(`agent-feedback-widget-item-${comment.source}`);
            if (comment.suggestion) {
                item.classList.add('agent-feedback-widget-item-suggestion');
            }
            this._itemElements.set(comment.id, item);

            // Header: meta (line-info + optional type badge) + hover actions.
            const itemHeader = $('div.agent-feedback-widget-item-header');
            const itemMeta = $('div.agent-feedback-widget-item-meta');

            const lineInfo = $('span.agent-feedback-widget-line-info');
            lineInfo.textContent = this._lineLabel(comment.startLine, comment.endLine);
            itemMeta.appendChild(lineInfo);

            const typeLabel = this._typeLabel(comment.kind);
            if (typeLabel) {
                const badge = $('span.agent-feedback-widget-item-type');
                badge.textContent = typeLabel;
                itemMeta.appendChild(badge);
            }
            itemHeader.appendChild(itemMeta);

            const text = $('div.agent-feedback-widget-text');
            const actions = this._buildItemActions(comment, item, text);
            itemHeader.appendChild(actions.container);
            item.appendChild(itemHeader);

            // Body text.
            text.appendChild(renderMarkdown(comment.text));
            item.appendChild(text);

            if (comment.suggestion?.edits.length) {
                item.appendChild(this._renderSuggestion(comment));
            }
            if (comment.replies?.length) {
                item.appendChild(this._renderReplies(comment.replies));
            }

            // Click navigates/focuses (ignoring action bar, reply input and text
            // selections) — mirrors production.
            this._listen(item, 'click', e => {
                const target = e.target as HTMLElement | null;
                if (target?.closest('.monaco-action-bar') || target?.closest('.agent-feedback-widget-add-reply')) {
                    return;
                }
                if (target?.closest('.agent-feedback-widget-text, .agent-feedback-widget-suggestion-text, .agent-feedback-widget-reply-text')) {
                    const selection = this._domNode.ownerDocument.defaultView?.getSelection();
                    if (selection && !selection.isCollapsed && this._domNode.contains(selection.anchorNode)) {
                        return;
                    }
                }
                this.focusFeedback(comment.id);
            });

            this._bodyNode.appendChild(item);
        }
    }

    private _buildItemActions(comment: VscodeComment, item: HTMLElement, text: HTMLElement): { container: HTMLElement; actions: ItemActions } {
        const container = $('div.agent-feedback-widget-item-actions');
        const bar = $('div.monaco-action-bar');
        const list = $('ul.actions-container');
        list.setAttribute('role', 'toolbar');

        const addReply = this._actionLabel('comment-discussion', 'Add to Comment');
        const edit = this._actionLabel('edit', 'Edit');
        const remove = this._actionLabel('close', 'Remove');

        const actions: ItemActions = {
            addReply, edit, remove,
            setEnabled: (enabled: boolean) => {
                for (const a of [addReply, edit, remove]) {
                    a.classList.toggle('disabled', !enabled);
                    a.tabIndex = enabled ? 0 : -1;
                }
            },
        };

        this._listen(addReply, 'click', e => { e.stopPropagation(); this._startAddingReply(comment, item, actions); });
        this._listen(edit, 'click', e => { e.stopPropagation(); this._startEditing(comment, text, actions); });
        this._listen(remove, 'click', e => { e.stopPropagation(); this._removeItem(comment.id); });

        for (const a of [addReply, edit, remove]) {
            const li = $('li.action-item');
            li.appendChild(a);
            list.appendChild(li);
        }
        bar.appendChild(list);
        container.appendChild(bar);
        return { container, actions };
    }

    private _actionLabel(codicon: string, ariaLabel: string): HTMLAnchorElement {
        const a = document.createElement('a');
        a.className = `action-label codicon codicon-${codicon}`;
        a.setAttribute('role', 'button');
        a.setAttribute('aria-label', ariaLabel);
        a.title = ariaLabel;
        a.tabIndex = 0;
        a.innerHTML = ICON_SVGS[codicon] ?? '';
        return a;
    }

    private _lineLabel(startLine: number, endLine?: number): string {
        return (endLine === undefined || endLine === startLine)
            ? `Line ${startLine}`
            : `Lines ${startLine}-${endLine}`;
    }

    private _typeLabel(kind: VscodeCommentKind): string | undefined {
        switch (kind) {
            case 'prReview': return 'PR Review';
            case 'agentReview': return 'Agent Review';
            default: return undefined;
        }
    }

    private _renderSuggestion(comment: VscodeComment): HTMLElement {
        const suggestionNode = $('div.agent-feedback-widget-suggestion');
        for (const edit of comment.suggestion?.edits ?? []) {
            const editNode = $('div.agent-feedback-widget-suggestion-edit');
            const header = $('div.agent-feedback-widget-suggestion-header');
            const end = edit.endLine ?? edit.startLine;
            header.textContent = end === edit.startLine
                ? `Suggested Change \u2022 Line ${edit.startLine}`
                : `Suggested Change \u2022 Lines ${edit.startLine}-${end}`;
            editNode.appendChild(header);

            const pre = $('pre.agent-feedback-widget-suggestion-text');
            pre.textContent = edit.newText;
            editNode.appendChild(pre);
            suggestionNode.appendChild(editNode);
        }
        return suggestionNode;
    }

    private _renderReplies(replies: readonly string[]): HTMLElement {
        const repliesNode = $('div.agent-feedback-widget-replies');
        for (const reply of replies) {
            const replyNode = $('div.agent-feedback-widget-reply');
            const replyText = $('div.agent-feedback-widget-reply-text');
            replyText.appendChild(renderMarkdown(reply));
            replyNode.appendChild(replyText);
            repliesNode.appendChild(replyNode);
        }
        return repliesNode;
    }

    // --- Interactive behaviour ------------------------------------------

    private _startEditing(comment: VscodeComment, textContainer: HTMLElement, actions: ItemActions): void {
        actions.setEnabled(false);
        const previous = Array.from(textContainer.childNodes);
        textContainer.textContent = '';
        textContainer.classList.add('editing');

        const textarea = document.createElement('textarea');
        textarea.className = 'agent-feedback-widget-edit-textarea';
        textarea.value = comment.text;
        textarea.rows = 1;
        textContainer.appendChild(textarea);

        const autoSize = (): void => {
            textarea.style.height = 'auto';
            if (textarea.scrollHeight > 0) { textarea.style.height = `${textarea.scrollHeight}px`; }
        };
        autoSize();

        const restore = (): void => {
            textContainer.classList.remove('editing');
            textContainer.textContent = '';
            for (const n of previous) { textContainer.appendChild(n); }
            actions.setEnabled(true);
        };

        this._listen(textarea, 'input', autoSize);
        this._listen(textarea, 'keydown', (e: KeyboardEvent) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                e.stopPropagation();
                const newText = textarea.value.trim();
                textContainer.classList.remove('editing');
                textContainer.textContent = '';
                textContainer.appendChild(renderMarkdown(newText || comment.text));
                actions.setEnabled(true);
            } else if (e.key === 'Escape') {
                e.preventDefault();
                e.stopPropagation();
                restore();
            }
        });
        this._listen(textarea, 'blur', restore);
        textarea.focus();
    }

    private _startAddingReply(comment: VscodeComment, item: HTMLElement, actions: ItemActions): void {
        if (item.querySelector('.agent-feedback-widget-add-reply')) {
            (item.querySelector('.agent-feedback-widget-edit-textarea') as HTMLTextAreaElement | null)?.focus();
            return;
        }
        actions.setEnabled(false);

        const replyContainer = $('div.agent-feedback-widget-add-reply');
        const textarea = document.createElement('textarea');
        textarea.className = 'agent-feedback-widget-edit-textarea';
        textarea.placeholder = 'Add a comment\u2026';
        textarea.rows = 1;
        replyContainer.appendChild(textarea);
        item.appendChild(replyContainer);

        const autoSize = (): void => {
            textarea.style.height = 'auto';
            if (textarea.scrollHeight > 0) { textarea.style.height = `${textarea.scrollHeight}px`; }
        };
        autoSize();

        const close = (): void => {
            replyContainer.remove();
            actions.setEnabled(true);
        };

        this._listen(textarea, 'input', autoSize);
        this._listen(textarea, 'keydown', (e: KeyboardEvent) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                e.stopPropagation();
                const value = textarea.value.trim();
                if (value) {
                    let repliesNode = item.querySelector('.agent-feedback-widget-replies');
                    if (!repliesNode) {
                        repliesNode = this._renderReplies([]);
                        item.insertBefore(repliesNode, replyContainer);
                    }
                    const replyNode = $('div.agent-feedback-widget-reply');
                    const replyText = $('div.agent-feedback-widget-reply-text');
                    replyText.appendChild(renderMarkdown(value));
                    replyNode.appendChild(replyText);
                    repliesNode.appendChild(replyNode);
                }
                close();
            } else if (e.key === 'Escape') {
                e.preventDefault();
                e.stopPropagation();
                close();
            }
        });
        this._listen(textarea, 'blur', close);
        textarea.focus();
    }

    private _removeItem(id: string): void {
        const item = this._itemElements.get(id);
        item?.remove();
        this._itemElements.delete(id);
    }

    // --- Public API ------------------------------------------------------

    expand(): void {
        this._isExpanded = true;
        this._domNode.classList.remove('collapsed');
        this._bodyNode.classList.remove('collapsed');
        this._updateToggleButton();
    }

    collapse(): void {
        this._isExpanded = false;
        this._domNode.classList.add('collapsed');
        this._bodyNode.classList.add('collapsed');
        this._updateToggleButton();
    }

    toggle(visible: boolean): void {
        this._domNode.classList.toggle('visible', visible);
    }

    /** Marks a single comment item as focused (VS Code's active-selection style). */
    focusFeedback(id: string): void {
        if (this._focusedId) {
            this._itemElements.get(this._focusedId)?.classList.remove('focused');
        }
        this._focusedId = id;
        this._itemElements.get(id)?.classList.add('focused');
    }

    private _listen<K extends keyof HTMLElementEventMap>(target: HTMLElement, type: K, handler: (e: HTMLElementEventMap[K]) => void): void {
        target.addEventListener(type, handler as EventListener);
        this._disposables.push(() => target.removeEventListener(type, handler as EventListener));
    }

    dispose(): void {
        for (const d of this._disposables) { d(); }
        this._disposables.length = 0;
        this._domNode.remove();
    }
}
