//
// Presenter that renders each comment from a CommentsModel as a VS Code
// agent-feedback card (the "comments-vscode" design), reusing the real
// VscodeCommentWidget. Maps the rendering-agnostic Comment onto a VscodeComment;
// the base class handles anchoring, stacking and lifecycle.
//

import type { Comment } from '../comments/commentsModel.js';
import { StackedCommentsPresenter, type StackWidget } from './stackedCommentsPresenter.js';
import { VscodeCommentWidget, type VscodeComment } from './vscodeCommentWidget.js';
import './vscodeCommentTokens.css';
import './vscodeCommentWidget.css';

export class VscodeStackedCommentsView extends StackedCommentsPresenter {
    protected createWidget(comment: Comment): StackWidget {
        const startLine = this.context?.resolveLine?.(comment.range.start) ?? 1;
        const vscodeComment: VscodeComment = {
            id: comment.id,
            source: 'prReview',
            kind: 'prReview',
            startLine,
            text: comment.body,
        };
        return new VscodeCommentWidget([vscodeComment], { expanded: true });
    }
}
