//
// Shared base for the "stacked card" comment presenters (VS Code V1 and V2).
// Owns the token-wrapped overlay layer, reconciles one card per comment against
// the model, and keeps them right-aligned + stacked. Subclasses only say how to
// build a card from a Comment.
//
// Two triggers drive the layout, because the geometry has two independent
// inputs: the autorun re-runs when comments or their rects change (edits,
// reflow), and a ResizeObserver re-runs when the editor resizes (width /
// centering changes that don't touch the rects). Without the observer the
// horizontal position would go stale on resize.
//

import { Disposable, autorun, type IObservable } from '@vscode/observables';
import type { SelectionRect } from '../../view/parts/selectionView.js';
import type { EditorView } from '../../view/editorView.js';
import type { Comment, CommentsModel } from '../comments/commentsModel.js';
import type { ICommentsPresenter, CommentsPresenterContext } from '../comments/commentsPresenter.js';
import { layoutRightAlignedStack, type StackItem } from './stackedRailLayout.js';

/** The minimal widget contract a subclass must produce. */
export interface StackWidget {
    readonly element: HTMLElement;
    dispose(): void;
}

interface Entry {
    readonly widget: StackWidget;
    readonly rects: IObservable<readonly SelectionRect[]>;
}

export abstract class StackedCommentsPresenter extends Disposable implements ICommentsPresenter {
    private readonly _layer: HTMLElement;
    private readonly _entries = new Map<string, Entry>();
    private _order: readonly string[] = [];
    private _pendingRevealCommentId: string | undefined;

    // Public so subclasses inherit a public constructor (the class is abstract,
    // so it still cannot be instantiated directly).
    constructor(
        protected readonly model: CommentsModel,
        protected readonly view: EditorView,
        protected readonly context?: CommentsPresenterContext,
    ) {
        super();
        // Token-wrapped overlay layer (supplies the `--vscode-*` theme variables
        // the card CSS consumes) that scrolls with the content and lets cards
        // overlap the text.
        this._layer = document.createElement('div');
        this._layer.className = context?.theme === 'light' ? 'vscode-comments-light' : 'vscode-comments-dark';
        this._layer.style.position = 'absolute';
        this._layer.style.inset = '0';
        this._layer.style.pointerEvents = 'none';
        this._layer.style.overflow = 'visible';
        // The `.vscode-comments-*` token wrapper paints `--vscode-editor-background`;
        // override it so this overlay never covers the editor content behind it.
        this._layer.style.background = 'transparent';
        this.view.overlayContainer.appendChild(this._layer);

        this._register({
            dispose: () => {
                for (const e of this._entries.values()) { e.widget.dispose(); }
                this._entries.clear();
                this._layer.remove();
            },
        });

        this._register(autorun(reader => {
            const comments = this.model.comments.read(reader);
            this._reconcile(comments);
            // Subscribe to each range's rects so reflow re-runs the layout.
            for (const c of comments) { this._entries.get(c.id)!.rects.read(reader); }
            this._relayout();
        }));

        // Editor width / centering changes don't touch the rects, so re-run the
        // (horizontal) layout when the element resizes too.
        const resizeObserver = new ResizeObserver(() => this._relayout());
        resizeObserver.observe(this.view.element);
        this._register({ dispose: () => resizeObserver.disconnect() });
    }

    /** Build the card DOM for a comment. Called once per new comment. */
    protected abstract createWidget(comment: Comment): StackWidget;

    revealComment(id: string): void {
        this._pendingRevealCommentId = id;
        this._revealPendingComment();
    }

    private _reconcile(comments: readonly Comment[]): void {
        this._order = comments.map(c => c.id);
        const seen = new Set(this._order);
        for (const comment of comments) {
            if (this._entries.has(comment.id)) { continue; }
            const widget = this.createWidget(comment);
            // Absolutely positioned so layoutRightAlignedStack's left/top apply
            // (not every widget sets this in its own CSS, e.g. the V2 card).
            widget.element.style.position = 'absolute';
            widget.element.style.pointerEvents = 'auto';
            this._layer.appendChild(widget.element);
            this._entries.set(comment.id, { widget, rects: this.view.rangeRects(comment.range) });
        }
        for (const [id, entry] of this._entries) {
            if (!seen.has(id)) {
                entry.widget.dispose();
                this._entries.delete(id);
            }
        }
    }

    private _relayout(): void {
        const items: StackItem[] = this._order
            .map(id => this._entries.get(id))
            .filter((e): e is Entry => e !== undefined)
            .map(e => ({ element: e.widget.element, rects: e.rects.get() }));
        layoutRightAlignedStack(this.view, items);
        this._revealPendingComment();
    }

    private _revealPendingComment(): void {
        const id = this._pendingRevealCommentId;
        if (!id) {
            return;
        }
        const element = this._entries.get(id)?.widget.element;
        if (!element || element.style.visibility === 'hidden') {
            return;
        }
        this._pendingRevealCommentId = undefined;
        element.scrollIntoView({ block: 'center', inline: 'nearest' });
    }
}
