import { Disposable, autorun, observableValue, type IObservable } from '@vscode/observables';

/**
 * Codicon "plus" (add) glyph shown on the submit action, matching VS Code's
 * agent-feedback input widget. Inlined as an SVG so the markdown editor doesn't
 * depend on the codicon font.
 */
const PLUS_SVG =
	`<svg viewBox="0 0 16 16" width="16" height="16" fill="currentColor" aria-hidden="true">`
	+ `<path d="M14 7v1H8v6H7V8H1V7h6V1h1v6h6z"></path>`
	+ `</svg>`;

export interface CommentInputWidgetOptions {
	/** Placeholder shown while the textarea is empty. Defaults to "Add Comment". */
	readonly placeholder?: string;
	/** Called after the textarea changes size. */
	readonly onDidChangeSize?: () => void;
	/**
	 * Called when the user submits a non-empty comment (Enter or the send
	 * button). The text is trimmed; never called with an empty string.
	 */
	readonly onSubmit?: (text: string) => void;
	/** Called when the user dismisses the input (Escape). */
	readonly onCancel?: () => void;
}

/**
 * A self-contained comment input box — a rounded panel with an auto-growing
 * textarea and a send button, styled after the gdocs/Word "add a comment"
 * affordance.
 *
 * This widget is *positioning-agnostic*: it only owns its own DOM and state.
 * A host (the comment-mode controller, or a fixture) mounts {@link element}
 * wherever it likes and is responsible for placing it relative to a selection.
 *
 * State is observable-driven (no framework): {@link value} reflects the live
 * textarea content; submit/cancel are reported through the option callbacks.
 */
export class CommentInputWidget extends Disposable {
	readonly element: HTMLElement;

	private readonly _textarea: HTMLTextAreaElement;
	private readonly _measure: HTMLSpanElement;
	private readonly _submitButton: HTMLButtonElement;

	private readonly _value = observableValue<string>(this, '');
	/** Live, untrimmed textarea content. */
	get value(): IObservable<string> { return this._value; }

	/** The raw textarea, exposed so a host can move focus into it (e.g. on Tab). */
	get inputElement(): HTMLTextAreaElement { return this._textarea; }

	constructor(private readonly _options?: CommentInputWidgetOptions) {
		super();

		this.element = document.createElement('div');
		this.element.className = 'md-comment-input';

		this._textarea = document.createElement('textarea');
		this._textarea.className = 'md-comment-input-textarea';
		this._textarea.rows = 1;
		this._textarea.placeholder = _options?.placeholder ?? 'Add Comment';
		this.element.appendChild(this._textarea);

		// Hidden element used to measure text width for auto-growing.
		this._measure = document.createElement('span');
		this._measure.className = 'md-comment-input-measure';
		this._measure.setAttribute('aria-hidden', 'true');
		this.element.appendChild(this._measure);

		const footer = document.createElement('div');
		footer.className = 'md-comment-input-actions';
		this.element.appendChild(footer);

		this._submitButton = document.createElement('button');
		this._submitButton.type = 'button';
		this._submitButton.className = 'md-comment-input-submit';
		this._submitButton.innerHTML = PLUS_SVG;
		this._submitButton.title = 'Comment';
		footer.appendChild(this._submitButton);

		// Clicking anywhere in the panel padding (not the button) focuses the
		// textarea. Stop the event from reaching the host editor, which would
		// otherwise move focus/selection out of the box on every click inside it.
		// The editor starts selection drags on `pointerdown`, so guard that.
		const onPanelPointerDown = (e: PointerEvent): void => {
			e.stopPropagation();
			if (e.target === this._textarea || this._submitButton.contains(e.target as Node)) { return; }
			e.preventDefault();
			this._textarea.focus();
		};
		this.element.addEventListener('pointerdown', onPanelPointerDown);
		this._register({ dispose: () => this.element.removeEventListener('pointerdown', onPanelPointerDown) });

		const onInput = (): void => {
			this._value.set(this._textarea.value, undefined);
			this._autoSize();
		};
		this._textarea.addEventListener('input', onInput);
		this._register({ dispose: () => this._textarea.removeEventListener('input', onInput) });

		const onKeyDown = (e: KeyboardEvent): void => {
			// The box lives inside the editor element, so its keystrokes would
			// otherwise bubble to the editor's key handler (moving the editor
			// caret, deleting document text, etc.). Keep every key inside the box —
			// the textarea handles its own editing (typing, arrows, delete) natively.
			e.stopPropagation();
			if (e.key === 'Escape') {
				e.preventDefault();
				this._options?.onCancel?.();
				return;
			}
			// Enter submits; Shift+Enter inserts a newline.
			if (e.key === 'Enter' && !e.shiftKey) {
				e.preventDefault();
				this._submit();
			}
		};
		this._textarea.addEventListener('keydown', onKeyDown);
		this._register({ dispose: () => this._textarea.removeEventListener('keydown', onKeyDown) });

		const onSubmitClick = (): void => this._submit();
		this._submitButton.addEventListener('click', onSubmitClick);
		this._register({ dispose: () => this._submitButton.removeEventListener('click', onSubmitClick) });

		// Keep the submit button enabled state in sync with the content.
		this._register(autorun(reader => {
			const hasText = this._value.read(reader).trim().length > 0;
			this._submitButton.disabled = !hasText;
			this.element.classList.toggle('md-comment-input-empty', !hasText);
		}));

		this._autoSize();
	}

	/** Move focus into the textarea (caret at the end). */
	focus(): void {
		this._textarea.focus();
		const end = this._textarea.value.length;
		this._textarea.setSelectionRange(end, end);
	}

	/** Replace the textarea content. */
	setText(text: string): void {
		this._textarea.value = text;
		this._value.set(text, undefined);
		this._autoSize();
	}

	/** Clear the textarea. */
	clear(): void {
		this.setText('');
	}

	private _submit(): void {
		const text = this._textarea.value.trim();
		if (!text) { return; }
		this._options?.onSubmit?.(text);
	}

	private _autoSize(): void {
		// Width: measure the text (or placeholder) and grow the textarea to fit,
		// clamped between a minimum and maximum — mirrors the reference widget so
		// the bubble hugs short content and wraps long content at the max width.
		const text = this._textarea.value || this._textarea.placeholder;
		this._measure.textContent = text;
		const textWidth = this._measure.scrollWidth;
		const minWidth = 150;
		const maxWidth = 400;
		const width = Math.min(Math.max(minWidth, textWidth + 10), maxWidth);
		this._textarea.style.width = `${width}px`;

		// Height: reset to auto, then grow to fit the content.
		this._textarea.style.height = 'auto';
		// While the textarea is detached (e.g. constructed before being mounted)
		// scrollHeight is 0; leaving height at `auto` keeps the natural one-row
		// height (and the placeholder visible) until a real measurement is
		// possible. Once mounted, grow to fit the content.
		const scrollHeight = this._textarea.scrollHeight;
		if (scrollHeight > 0) {
			this._textarea.style.height = `${scrollHeight}px`;
		}
		this._options?.onDidChangeSize?.();
	}
}
