//
// Pixel-for-pixel replica of the "Markdown comment" frames from the Figma
// "Comment / Feedback widget" board
// (https://www.figma.com/design/lWE17f1tRRDXWsbxTcbsmo/Polish-Push-May---June-2026?node-id=4379-10808).
//
// It reproduces the three states of the markdown comment card:
//   1. 'short'     — a single short line, no toggle.
//   2. 'collapsed' — a long body clamped to three lines with a "See more" link.
//   3. 'expanded'  — the full body with a "See less" link.
//
// Design tokens (from Figma):
//   editorWidget/background   #202122
//   editorHoverWidget/border  #2a2b2c
//   foreground                #bfbfbf
//   icon/foreground           #8c8c8c
//   textLink/foreground       #48a0c7
//   Outer radius              8px
//   size40 / size60 / size80  4 / 6 / 8px
//   Heading 3  SF Pro Text Semibold 13
//   Body 1     SF Pro Text Regular  13
//   Label 1    SF Pro Text Regular  12
//

/** The three markdown-comment states captured in the Figma frames. */
export type VsCodeCommentV2State = 'short' | 'collapsed' | 'expanded';

export interface VsCodeCommentWidgetV2Options {
    /** Author label shown in the header (e.g. `@username`). */
    readonly username: string;
    /** The comment body (rendered as plain text; long bodies get a toggle). */
    readonly body: string;
    /**
     * Initial state. `'short'` hides the toggle entirely; `'collapsed'` and
     * `'expanded'` show a "See more" / "See less" toggle. Defaults to `'short'`.
     */
    readonly state?: VsCodeCommentV2State;
    /** Called when the user toggles between collapsed and expanded. */
    readonly onToggle?: (expanded: boolean) => void;
    /**
     * If provided, an edit button is shown in the header and invokes this on
     * click. When omitted the edit button is hidden.
     */
    readonly onEdit?: () => void;
    /**
     * If provided, the delete (trash) button invokes this on click. When omitted
     * the delete button is hidden.
     */
    readonly onDelete?: () => void;
}

const DOM_HELPER_TAG = /^([a-z0-9]+)/i;

/** VS Code's `dom.$('tag.a.b')` shorthand, reduced to what we use. */
function $(selector: string): HTMLElement {
    const tag = DOM_HELPER_TAG.exec(selector)?.[1] ?? 'div';
    const el = document.createElement(tag);
    const classes = selector.slice(tag.length).split('.').filter(Boolean);
    if (classes.length) {
        el.className = classes.join(' ');
    }
    return el;
}

/**
 * Inline Feather-style icons (stroke="currentColor"), matching the crisp look of
 * VS Code's codicons and the sibling {@link VscodeCommentWidget}.
 */
function feather(inner: string): string {
    return `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${inner}</svg>`;
}

const ICON_SVGS: Record<string, string> = {
    'edit': feather('<path d="M12 20h9"></path><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"></path>'),
    'trash': feather('<polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line>'),
};

/** An icon-only action button carrying the inline Feather SVG for `name`. */
function actionButton(name: string, label: string): HTMLButtonElement {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'vscode-comment-widget-v2-action';
    btn.setAttribute('aria-label', label);
    btn.title = label;
    btn.innerHTML = ICON_SVGS[name] ?? '';
    return btn;
}
export class VsCodeCommentWidgetV2 {
    private readonly _domNode: HTMLElement;
    private readonly _textNode: HTMLParagraphElement;
    private readonly _toggleNode?: HTMLButtonElement;
    private readonly _onToggle?: (expanded: boolean) => void;

    private _state: VsCodeCommentV2State;
    private readonly _disposables: (() => void)[] = [];
    private readonly _onToggleClick = (e: MouseEvent): void => {
        e.preventDefault();
        this.toggle();
    };

    get element(): HTMLElement { return this._domNode; }

    get expanded(): boolean { return this._state === 'expanded'; }

    constructor(options: VsCodeCommentWidgetV2Options) {
        this._state = options.state ?? 'short';
        this._onToggle = options.onToggle;

        // Card root — "PR Review Comment" frame.
        this._domNode = $('div.vscode-comment-widget-v2');

        // Header row: title-group (username) + actions (edit / trash).
        const header = $('div.vscode-comment-widget-v2-header');

        const titleGroup = $('div.vscode-comment-widget-v2-title-group');
        const username = $('span.vscode-comment-widget-v2-username');
        username.textContent = options.username;
        titleGroup.appendChild(username);
        header.appendChild(titleGroup);

        const actions = $('div.vscode-comment-widget-v2-actions');
        if (options.onEdit) {
            actions.appendChild(this._actionButton('edit', 'Edit', options.onEdit));
        }
        if (options.onDelete) {
            actions.appendChild(this._actionButton('trash', 'Delete', options.onDelete));
        }
        header.appendChild(actions);

        this._domNode.appendChild(header);

        // Body: comment text + optional "See more" / "See less" toggle.
        const body = $('div.vscode-comment-widget-v2-body');

        this._textNode = document.createElement('p');
        this._textNode.className = 'vscode-comment-widget-v2-text';
        this._textNode.textContent = options.body;
        body.appendChild(this._textNode);

        if (this._state !== 'short') {
            const toggle = document.createElement('button');
            toggle.type = 'button';
            toggle.className = 'vscode-comment-widget-v2-toggle';
            toggle.addEventListener('click', this._onToggleClick);
            this._toggleNode = toggle;
            body.appendChild(toggle);
        }

        this._domNode.appendChild(body);

        this._applyState();
    }

    /** Flip between the collapsed and expanded states (no-op for `'short'`). */
    toggle(): void {
        if (this._state === 'short') {
            return;
        }
        this._state = this._state === 'expanded' ? 'collapsed' : 'expanded';
        this._applyState();
        this._onToggle?.(this._state === 'expanded');
    }

    private _applyState(): void {
        this._domNode.classList.toggle('vscode-comment-widget-v2--collapsed', this._state === 'collapsed');
        this._domNode.classList.toggle('vscode-comment-widget-v2--expanded', this._state === 'expanded');
        if (this._toggleNode) {
            this._toggleNode.textContent = this._state === 'expanded' ? 'See less' : 'See more';
        }
    }

    /** A header action button that runs `onClick` (and cleans up on dispose). */
    private _actionButton(name: string, label: string, onClick: () => void): HTMLButtonElement {
        const button = actionButton(name, label);
        const handler = (e: MouseEvent): void => {
            e.preventDefault();
            e.stopPropagation();
            onClick();
        };
        button.addEventListener('click', handler);
        this._disposables.push(() => button.removeEventListener('click', handler));
        return button;
    }

    dispose(): void {
        this._toggleNode?.removeEventListener('click', this._onToggleClick);
        for (const dispose of this._disposables) { dispose(); }
        this._domNode.remove();
    }
}
