//
// Presenter that renders each comment from a CommentsModel as the Figma
// "Markdown comment" card (the V3 design), reusing the real
// VsCodeCommentWidgetV2. The base class handles anchoring, stacking and
// lifecycle.
//

import type { Comment } from '../comments/commentsModel.js';
import { StackedCommentsPresenter, type StackWidget } from './stackedCommentsPresenter.js';
import { VsCodeCommentWidgetV2 } from './vscodeCommentWidgetV2.js';
import './vscodeCommentTokens.css';
import './vscodeCommentWidgetV2.css';

/** Bodies longer than this open collapsed (with a "See more" toggle). */
const COLLAPSE_THRESHOLD = 80;

export class VsCodeV2CommentsView extends StackedCommentsPresenter {
    protected createWidget(comment: Comment): StackWidget {
        return new VsCodeCommentWidgetV2({
            username: comment.author ?? 'You',
            body: comment.body,
            state: comment.body.length > COLLAPSE_THRESHOLD ? 'collapsed' : 'short',
            // Edit is intentionally omitted (hidden) for now. Delete removes the
            // comment from the shared model; the autorun then disposes the card.
            onDelete: () => this.model.remove(comment.id),
        });
    }
}
