//
// Composition root that maps a design id to a presenter factory. This is the one
// place that knows all three renderings; the core (CommentsModel /
// commentsPresenter) stays unaware of the concrete designs. Hosts (the demo, the
// fixtures) pick a design here and swap it over a shared CommentsModel.
//

import { CommentsView } from '../comments/commentsView.js';
import type { CommentsPresenterFactory } from '../comments/commentsPresenter.js';
import { VscodeStackedCommentsView } from './vscodeStackedCommentsView.js';
import { VsCodeV2CommentsView } from './vscodeV2CommentsView.js';
import '../comments/comments.css';

/** The available comment rendering designs. */
export type CommentsDesign = 'connected' | 'vscode' | 'vscode-v2';

/** Human-readable labels (for pickers / dropdowns). */
export const COMMENTS_DESIGN_LABELS: Record<CommentsDesign, string> = {
    'connected': 'Connected lines (original)',
    'vscode': 'VS Code cards',
    'vscode-v2': 'Markdown cards (V3)',
};

/** design id → presenter factory over a shared CommentsModel + EditorView. */
export const COMMENTS_DESIGNS: Record<CommentsDesign, CommentsPresenterFactory> = {
    'connected': (model, view) => new CommentsView(model, view),
    'vscode': (model, view, ctx) => new VscodeStackedCommentsView(model, view, ctx),
    'vscode-v2': (model, view, ctx) => new VsCodeV2CommentsView(model, view, ctx),
};
