import { Disposable, autorun, type IObservable, type IReader } from '@vscode/observables';
import type { SelectionRect } from '../../view/parts/selectionView.js';
import { buildConnectedPath } from '../../view/parts/selectionView.js';
import type { EditorView } from '../../view/editorView.js';
import type { Comment, CommentsModel } from './commentsModel.js';

const SVG_NS = 'http://www.w3.org/2000/svg';

/** Layout constants (px). */
const RAIL_MIN = 260;
const RAIL_MAX = 320;
const RAIL_FRACTION = 0.32;
/** Gap between the content's right edge and the rail. */
const RAIL_GAP = 28;
/** Gap between the rail and the editor's right edge. */
const RAIL_EDGE = 16;
/** Vertical gap between stacked cards. */
const CARD_GAP = 12;
/** Where on the card the leader attaches, measured from the card top. */
const LEADER_CARD_INSET = 18;
/** Corner radius of the range highlight. */
const HIGHLIGHT_RADIUS = 4;
/** Stroke width of the leader line (must match .md-comment-leader-path). */
const LEADER_WIDTH = 2;
/** How far the leader starts inside the highlight so the seam is hidden under
 * the (same-colored) fill. */
const LEADER_OVERLAP = 10;

/** Per-comment DOM + state, reconciled against the model's comment list. */
interface CommentEntry {
	comment: Comment;
	rects: IObservable<readonly SelectionRect[]>;
	readonly group: SVGGElement;
	readonly shapePath: SVGPathElement;
	readonly leaderPath: SVGPathElement;
	readonly card: HTMLElement;
	readonly bodyEl: HTMLElement;
	readonly authorEl: HTMLElement;
	readonly avatarEl: HTMLElement;
	readonly timeEl: HTMLElement;
	readonly disposables: { dispose(): void }[];
}

/**
 * Renders persistent comments as a gdocs-style side rail: each comment's range
 * is highlighted (reusing the editor's selection geometry via
 * {@link EditorView.rangeRects}), a leader line curves from the bottom of that
 * highlight to a card stacked in the right rail, and cards never overlap.
 *
 * Everything is mounted into {@link EditorView.overlayContainer} so it shares
 * the selection/caret coordinate space and scrolls with the document. When the
 * editor's natural right margin is too narrow for the rail, the view reserves
 * proportional space by padding the editor on the right — but only while there
 * are comments.
 */
export class CommentsView extends Disposable {
	private readonly _layer: SVGSVGElement;
	private readonly _entries = new Map<string, CommentEntry>();

	constructor(
		private readonly _model: CommentsModel,
		private readonly _view: EditorView,
	) {
		super();

		this._layer = this._createLayer('md-comment-shapes');
		this._view.overlayContainer.appendChild(this._layer);

		this._register({
			dispose: () => {
				this._layer.remove();
				for (const entry of this._entries.values()) { this._disposeEntry(entry); }
				this._entries.clear();
				this._view.element.style.paddingRight = '';
			},
		});

		this._register(autorun(reader => this._update(reader)));
	}

	private _createLayer(className: string): SVGSVGElement {
		const svg = document.createElementNS(SVG_NS, 'svg');
		svg.setAttribute('class', className);
		return svg;
	}

	private _update(reader: IReader): void {
		const comments = this._model.comments.read(reader);
		const hoveredId = this._model.hoveredId.read(reader);

		this._reconcile(comments);

		// Read every comment's rects so the autorun re-runs when the layout
		// changes (e.g. reflow, resize).
		const items = comments.map(comment => {
			const entry = this._entries.get(comment.id)!;
			return { entry, rects: entry.rects.read(reader) };
		});

		this._layout(items);
		this._applyHover(hoveredId);
	}

	/** Create/update/remove per-comment DOM to match `comments`. */
	private _reconcile(comments: readonly Comment[]): void {
		const seen = new Set<string>();
		for (const comment of comments) {
			seen.add(comment.id);
			const existing = this._entries.get(comment.id);
			if (!existing) {
				this._entries.set(comment.id, this._createEntry(comment));
				continue;
			}
			// Re-anchor if the range changed; refresh content always.
			if (existing.comment.range !== comment.range) {
				existing.rects = this._view.rangeRects(comment.range);
			}
			existing.comment = comment;
			this._fillCard(existing);
		}
		for (const [id, entry] of this._entries) {
			if (!seen.has(id)) {
				this._disposeEntry(entry);
				this._entries.delete(id);
			}
		}
	}

	private _createEntry(comment: Comment): CommentEntry {
		// Highlight fill and leader stroke live in one opacity group and share a
		// solid color, so their overlap never darkens and the seam is invisible.
		// The leader is drawn first (under the fill) so its overlap is hidden.
		const group = document.createElementNS(SVG_NS, 'g');
		group.setAttribute('class', 'md-comment-group');
		this._layer.appendChild(group);

		const leaderPath = document.createElementNS(SVG_NS, 'path');
		leaderPath.setAttribute('class', 'md-comment-leader-path');
		group.appendChild(leaderPath);

		const shapePath = document.createElementNS(SVG_NS, 'path');
		shapePath.setAttribute('class', 'md-comment-shape-path');
		group.appendChild(shapePath);

		const card = document.createElement('div');
		card.className = 'md-comment-card';

		const header = document.createElement('div');
		header.className = 'md-comment-card-header';
		const avatarEl = document.createElement('span');
		avatarEl.className = 'md-comment-avatar';
		const authorEl = document.createElement('span');
		authorEl.className = 'md-comment-author';
		const timeEl = document.createElement('span');
		timeEl.className = 'md-comment-time';
		const menuEl = document.createElement('span');
		menuEl.className = 'md-comment-menu';
		menuEl.textContent = '\u22EF'; // ⋯
		header.append(avatarEl, authorEl, timeEl, menuEl);

		const bodyEl = document.createElement('div');
		bodyEl.className = 'md-comment-body';

		const reply = document.createElement('button');
		reply.type = 'button';
		reply.className = 'md-comment-reply';
		reply.textContent = 'Reply';

		card.append(header, bodyEl, reply);
		this._view.overlayContainer.appendChild(card);

		const entry: CommentEntry = {
			comment,
			rects: this._view.rangeRects(comment.range),
			group, shapePath, leaderPath,
			card, bodyEl, authorEl, avatarEl, timeEl,
			disposables: [],
		};

		const setHover = (on: boolean): void => this._model.hoveredId.set(on ? comment.id : undefined, undefined);
		const enter = (): void => setHover(true);
		const leave = (): void => setHover(false);
		// Hover is driven from the card only; the highlight layer stays
		// non-interactive so it never blocks selecting the underlying text.
		card.addEventListener('mouseenter', enter);
		card.addEventListener('mouseleave', leave);
		entry.disposables.push({
			dispose: () => {
				card.removeEventListener('mouseenter', enter);
				card.removeEventListener('mouseleave', leave);
			},
		});

		this._fillCard(entry);
		return entry;
	}

	private _fillCard(entry: CommentEntry): void {
		const { comment } = entry;
		const author = comment.author ?? 'You';
		entry.authorEl.textContent = author;
		entry.avatarEl.textContent = _initials(author);
		entry.timeEl.textContent = comment.createdAt !== undefined ? _relativeTime(comment.createdAt) : '';
		entry.bodyEl.textContent = comment.body;
	}

	private _disposeEntry(entry: CommentEntry): void {
		for (const d of entry.disposables) { d.dispose(); }
		entry.group.remove();
		entry.card.remove();
	}

	/** Position highlights, cards (stacked) and leader lines. */
	private _layout(items: readonly { entry: CommentEntry; rects: readonly SelectionRect[] }[]): void {
		const root = this._view.element;
		const overlay = this._view.overlayContainer;

		if (items.length === 0) {
			root.style.paddingRight = '';
			this._layer.style.display = 'none';
			return;
		}
		this._layer.style.display = '';

		// --- Reserve rail space (only when comments exist). Compute the target
		// right padding analytically from stable inputs, so it is idempotent and
		// does not thrash the layout: the editor's border-box width doesn't change
		// with padding, and the content column is centered (margin-inline:auto)
		// with a known max-width. We deliberately avoid the old "clear padding →
		// measure → re-apply" dance: now that the editor re-measures on reflow,
		// toggling padding to measure would oscillate.
		const rootWidth = this._view.coordinateSpace.capture().toLocalRect(root.getBoundingClientRect()).width;
		const cs = getComputedStyle(overlay);
		const maxW = parseFloat(cs.maxWidth);
		const padX = (parseFloat(cs.paddingLeft) || 0) + (parseFloat(cs.paddingRight) || 0);
		const borderX = (parseFloat(cs.borderLeftWidth) || 0) + (parseFloat(cs.borderRightWidth) || 0);
		// Full outer width of the content column at its max-width (accounting for
		// box-sizing). `NaN` max-width (limited mode off) → content spans the root.
		const contentMaxOuter = Number.isNaN(maxW)
			? rootWidth
			: (cs.boxSizing === 'border-box' ? maxW : maxW + padX + borderX);
		// The natural right margin when no rail padding is applied (content centered).
		const naturalRight = Math.max(0, (rootWidth - Math.min(contentMaxOuter, rootWidth)) / 2);

		const railWidth = Math.round(Math.max(RAIL_MIN, Math.min(RAIL_MAX, rootWidth * RAIL_FRACTION)));
		const need = railWidth + RAIL_GAP + RAIL_EDGE;
		// While the content still has margins, padding re-centers it, so only half
		// of each added pixel becomes right margin — reserve twice the shortfall.
		// But cap at `need`: once the content fills the padding box (no margins),
		// every added pixel becomes right gap, so `need` is all that's required.
		// The old code used the uncapped `2 × shortfall`, which in narrow viewports
		// massively over-reserved and collapsed the content column.
		const pad = naturalRight >= need ? 0 : Math.min(2 * (need - naturalRight), need);
		const padStr = pad > 0 ? `${Math.ceil(pad)}px` : '';
		if (root.style.paddingRight !== padStr) {
			root.style.paddingRight = padStr;
		}

		// Re-capture after reservation because centering may move the overlay's
		// local origin relative to the root.
		const rootRect = this._view.coordinateSpace.capture().toLocalRect(root.getBoundingClientRect());
		const railLeftLocal = rootRect.right - RAIL_EDGE - railWidth;
		// Right edge of the content box (overlay-local): the leader runs straight to
		// here (so it never crosses text) and only curves beyond it, in the margin.
		const contentRightLocal = overlay.clientWidth;

		// Desired vertical anchors.
		const placed = items.map(({ entry, rects }) => {
			entry.card.style.left = `${railLeftLocal}px`;
			entry.card.style.width = `${railWidth}px`;
			const anchor = _lineStart(rects);
			const desiredTop = rects.length > 0 ? Math.min(...rects.map(r => r.y)) : 0;
			return { entry, rects, anchor, desiredTop };
		});

		// Stack: sort by desired top, push each down so they never overlap.
		placed.sort((a, b) => a.desiredTop - b.desiredTop);
		let prevBottom = -Infinity;
		for (const p of placed) {
			const top = Math.max(p.desiredTop, prevBottom + CARD_GAP);
			p.entry.card.style.top = `${top}px`;
			const height = p.entry.card.offsetHeight;
			prevBottom = top + height;

			// The highlight is a filled shape painted exactly like a normal
			// selection (same rects, same rounded corners). The leader is a
			// same-colored stroke drawn *under* the fill, starting inside the
			// highlight (its seam hidden by the fill) with its bottom edge on the
			// selection bottom; it runs straight through the content, then curves
			// to the card in the margin.
			p.entry.shapePath.setAttribute('d', buildConnectedPath(p.rects, HIGHLIGHT_RADIUS));
			p.entry.leaderPath.setAttribute('d', p.anchor
				? _leaderLine(p.anchor, contentRightLocal, { x: railLeftLocal, y: top + LEADER_CARD_INSET })
				: '');
		}
	}

	private _applyHover(hoveredId: string | undefined): void {
		for (const [id, entry] of this._entries) {
			const hovered = id === hoveredId;
			entry.card.classList.toggle('md-comment-card-hovered', hovered);
			entry.group.classList.toggle('md-comment-group-hovered', hovered);
		}
	}
}

/** Where the leader leaves the highlight: a few px inside the squared bottom-right
 * corner, with the y centered on the stroke so the stroke's bottom edge sits
 * exactly on the selection's bottom edge. The x starts inside the highlight by
 * {@link LEADER_OVERLAP} so the seam is hidden under the (same-colored) fill. */
function _lineStart(rects: readonly SelectionRect[]): { x: number; y: number } | undefined {
	if (rects.length === 0) { return undefined; }
	let best = rects[0];
	for (const r of rects) {
		if (r.y + r.height > best.y + best.height) { best = r; }
	}
	const rightEdge = best.x + best.width;
	const x = Math.max(best.x, rightEdge - LEADER_OVERLAP);
	return { x, y: best.y + best.height - LEADER_WIDTH / 2 };
}

/**
 * Leader centerline (stroked): starts horizontal along the selection bottom from
 * `start` to `bendX` (content right edge) so it never crosses text and leaves
 * the highlight tangentially, then a smooth cubic in the margin to `to` (the
 * card). The straight→curve join is tangent-continuous, so the whole line is
 * smooth.
 */
function _leaderLine(start: { x: number; y: number }, bendX: number, to: { x: number; y: number }): string {
	const bend = Math.max(bendX, start.x + 12);
	const dx = to.x - bend;
	const c1x = bend + dx * 0.55;
	const c2x = to.x - dx * 0.45;
	return `M ${start.x} ${start.y} L ${bend} ${start.y} C ${c1x} ${start.y}, ${c2x} ${to.y}, ${to.x} ${to.y}`;
}

function _initials(name: string): string {
	const parts = name.trim().split(/\s+/).filter(Boolean);
	if (parts.length === 0) { return '?'; }
	const first = parts[0][0] ?? '';
	const second = parts.length > 1 ? parts[parts.length - 1][0] ?? '' : '';
	return (first + second).toUpperCase();
}

function _relativeTime(epochMs: number): string {
	const deltaSec = Math.max(0, Math.round((Date.now() - epochMs) / 1000));
	if (deltaSec < 60) { return 'just now'; }
	const min = Math.round(deltaSec / 60);
	if (min < 60) { return `${min}m ago`; }
	const hours = Math.round(min / 60);
	if (hours < 24) { return `${hours}h ago`; }
	const days = Math.round(hours / 24);
	return `${days}d ago`;
}
